function makePackingMessage(boxCount, minutesPerBox) {
  const packingMinutes = boxCount * minutesPerBox;
  return `상자 ${boxCount}개 포장, 총 ${packingMinutes}분`;
}
console.log(makePackingMessage(4, 6));

